            let children: Vec<u32> = node
                .children
                .iter()
                .copied()
                .filter(|c| self.tree.nodes.contains_key(c))
                .collect();
            let prev = self.sent_children.entry(id).or_default();
            cmds.extend(children_diff(id, prev, &children));
            *prev = children;
