            assert_eq!(pathland_qt_layer_widget_preferred(2, 0), 100.0);
            // Child 3 (WIDTH FILL) -> Layout.fillWidth set.
            assert_eq!(pathland_qt_layer_widget_fill(3, 0), 1);
            // Root ALIGNMENT=FILL -> children fill the cross axis (height).
